import { Routes, Route } from "react-router-dom";
import Home from "./components/Home";
import ZomatoUpload from "./components/ZomatoUpload";

function App() {
  return (
    <Routes>
      <Route path="/" element={<Home />} />
      <Route path="/platform/zomato" element={<ZomatoUpload />} />
      <Route path="/platform/swiggy" element={<div className="container"><h1>Swiggy - Coming Soon</h1></div>} />
      <Route path="/platform/blinkit" element={<div className="container"><h1>Blinkit - Coming Soon</h1></div>} />
    </Routes>
  );
}

export default App;
